/**
 * The committed mixed project under `tests/fixtures/mixed`: `.cerial` and TypeScript declarations referring to
 * each other, generated by the real CLI from its own config. Needs no database.
 *
 * Every run works on a temp copy, because `cerial generate` writes `cerial/handles.ts` beside the sources and the
 * committed project must never receive one.
 */

import { afterAll, beforeAll, describe, expect, it } from 'bun:test';
import { existsSync } from 'node:fs';
import { readdir, readFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { mixedProject, removeMixedProjects } from './mixed-merge-project';

afterAll(removeMixedProjects);

const FIXTURE = join(import.meta.dir, '../fixtures/mixed');
const BIN = resolve(import.meta.dir, '../../bin/cerial.ts');

async function fixtureFiles(omit: readonly string[] = []): Promise<Record<string, string>> {
  const names = (await readdir(FIXTURE, { recursive: true })).filter(
    (name) => /\.(cerial|ts)$/.test(name) && !omit.includes(name),
  );
  const files = await Promise.all(names.map(async (name) => [name, await readFile(join(FIXTURE, name), 'utf8')]));

  return Object.fromEntries(files);
}

async function generate(omit: readonly string[] = []): Promise<{ dir: string; code: number; output: string }> {
  const dir = await mixedProject(await fixtureFiles(omit));
  const proc = Bun.spawn([process.execPath, 'run', BIN, 'generate', '-y'], {
    cwd: dir,
    stdout: 'pipe',
    stderr: 'pipe',
  });
  const [stdout, stderr] = await Promise.all([new Response(proc.stdout).text(), new Response(proc.stderr).text()]);

  return { dir, code: await proc.exited, output: stdout + stderr };
}

// Models, objects, tuples, literals and enums each get their own file under the client
async function generated(dir: string, path: string): Promise<string> {
  return readFile(join(dir, 'client', path), 'utf8');
}

// The body of `export interface <name> {`, so a field is asserted on its own model rather than found anywhere
function declaration(text: string, name: string): string {
  const start = text.indexOf(`export interface ${name} {`);
  if (start < 0) return '';

  return text.slice(start, text.indexOf('\n}', start));
}

// One run serves every assertion; each test that needs a project the CLI refused generates its own
let mixed: Awaited<ReturnType<typeof generate>>;

beforeAll(async () => {
  mixed = await generate();
});

describe('the mixed project through the CLI', () => {
  it('generates a client holding the models and the declarations of both syntaxes', async () => {
    expect(mixed.code, mixed.output).toBe(0);
    const files = (await readdir(join(mixed.dir, 'client'), { recursive: true })).sort();

    for (const file of [
      'models/account.ts',
      'models/purchase.ts',
      'models/ticket.ts',
      'objects/address.ts',
      'objects/meta.ts',
      'tuples/point.ts',
      'tuples/pair.ts',
      'literals/level.ts',
      'literals/priority.ts',
      'enums/role.ts',
      'enums/status.ts',
    ]) {
      expect(files).toContain(file);
    }
  });

  it('types the fields of a .cerial model by the four TypeScript declarations', async () => {
    const account = declaration(await generated(mixed.dir, 'models/account.ts'), 'Account');

    expect(account).toMatch(/address: Address;/);
    expect(account).toMatch(/spot: Point;/);
    expect(account).toMatch(/tier: Level;/);
    expect(account).toMatch(/role: RoleEnumType;/);
  });

  it('types the fields of a TypeScript model by the four .cerial declarations', async () => {
    const purchase = declaration(await generated(mixed.dir, 'models/purchase.ts'), 'Purchase');

    expect(purchase).toMatch(/meta: Meta;/);
    expect(purchase).toMatch(/pair: Pair;/);
    expect(purchase).toMatch(/priority: Priority;/);
    expect(purchase).toMatch(/status: StatusEnumType;/);
  });

  it('relates a TypeScript model to a .cerial one through its handle, and back by name', async () => {
    const purchase = await generated(mixed.dir, 'models/purchase.ts');
    const ticket = await generated(mixed.dir, 'models/ticket.ts');

    expect(declaration(purchase, 'Purchase')).toMatch(/accountId: CerialId<number>;/);
    expect(purchase).toMatch(/account\?: AccountWhere;/);
    expect(declaration(ticket, 'Ticket')).toMatch(/purchaseId\?: CerialId<number>;/);
    expect(ticket).toMatch(/purchase\?: PurchaseWhere;/);
  });

  it('writes the handles into the copy and leaves the committed project alone', () => {
    expect(existsSync(join(mixed.dir, 'schema', 'cerial', 'handles.ts'))).toBe(true);
    expect(existsSync(join(FIXTURE, 'schema', 'cerial'))).toBe(false);
    expect(existsSync(join(FIXTURE, 'client'))).toBe(false);
  });
});

describe('each half of the project is load-bearing', () => {
  it('fails on an unknown type once the TypeScript half is removed', async () => {
    const { code, output } = await generate(['schema/purchase.schema.ts']);

    expect(code).not.toBe(0);
    expect(output).toContain('Invalid field type: Address');
  });

  it('fails on a missing handle once the .cerial half is removed', async () => {
    const { code, output } = await generate(['schema/account.cerial']);

    expect(code).not.toBe(0);
    expect(output).toMatch(/handles/);
  });
});
